import{_ as t,o as a,c as o,X as d}from"./chunks/framework.pSp8ynCZ.js";const u=JSON.parse('{"title":"Using PyCellPack","titleTemplate":":title · PyCellPack","description":"","frontmatter":{},"headers":[],"relativePath":"python/docs/index.md","filePath":"python/docs/index.md"}'),r={name:"python/docs/index.md"};function s(n,e,c,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="using-pycellpack" tabindex="-1">Using PyCellPack <a class="header-anchor" href="#using-pycellpack" aria-label="Permalink to &quot;Using PyCellPack&quot;">​</a></h1><p>PyCellPack stores numeric matrices in compressed CellPack streams and reads selected rows with native worker threads. Use it to prepare a matrix once, align datasets to a common gene vocabulary, and deliver ordered training batches.</p><h2 id="choose-your-path" tabindex="-1">Choose your path <a class="header-anchor" href="#choose-your-path" aria-label="Permalink to &quot;Choose your path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Start with</th><th>Result</th></tr></thead><tbody><tr><td>Learn the complete matrix workflow</td><td><a href="/cellpack-docs/python/docs/quickstart.html">Quickstart</a></td><td>A <code>.cpk</code> file and a NumPy selection</td></tr><tr><td>Select, reorder, convert, or reuse buffers</td><td><a href="/cellpack-docs/python/docs/storage.html">Matrix access</a></td><td>NumPy arrays or NumPy-backed CSR</td></tr><tr><td>Align different gene panels</td><td><a href="/cellpack-docs/python/docs/alignment.html">Gene alignment</a></td><td>Explicit source and output ID maps</td></tr><tr><td>Train from one or several datasets</td><td><a href="/cellpack-docs/python/docs/dataloader.html">Training batches</a></td><td>Dictionaries of CPU or CUDA Tensors</td></tr><tr><td>Generate model-specific fields</td><td><a href="/cellpack-docs/python/docs/process-functions.html">Process functions</a></td><td>Tokens, values, targets, and other named fields</td></tr><tr><td>Control outputs and ownership directly</td><td><a href="/cellpack-docs/python/docs/native-loader.html">Native loading</a></td><td>NumPy batches backed by a bounded ring</td></tr><tr><td>Cache repeated reads and inspect work</td><td><a href="/cellpack-docs/python/docs/planning.html">Planning and diagnostics</a></td><td>Plans, memory estimates, and run statistics</td></tr><tr><td>Use annotated matrices</td><td><a href="/cellpack-docs/python/docs/anndata.html">AnnData and H5CP</a></td><td>Lazy matrices with annotations</td></tr><tr><td>Share a producer on one host</td><td><a href="/cellpack-docs/python/docs/distributed.html">Distributed loading</a></td><td>One producer with per-rank consumers</td></tr></tbody></table><p>Read <a href="/cellpack-docs/python/docs/installation.html">installation</a>, then run the quickstart. The <a href="/cellpack-docs/python/api/">API reference</a> lists signatures, parameters, results, and lifecycle contracts. The <a href="/cellpack-docs/python/training/">Training</a> section provides complete integration programs.</p><h2 id="objects-you-will-use" tabindex="-1">Objects you will use <a class="header-anchor" href="#objects-you-will-use" aria-label="Permalink to &quot;Objects you will use&quot;">​</a></h2><p><code>File</code> identifies an encoded stream. <code>Store</code> describes an immutable, lazy matrix view over it. A read decodes that view into an array; indexing alone does not decode values.</p><p>For training, wrap a file-backed Store in <code>ScDataset</code>, describe sample order with corpus <code>Accesses</code>, and iterate <code>ScDataLoader</code>. For direct NumPy delivery, register files in <code>DataSource</code>, describe outputs with <code>OutputSchema</code>, and start a <code>Loader</code> run.</p><p>PyCellPack does not infer gene identity from column positions or choose epoch sampling policy. Supply both explicitly. Streams store matrix values and positional metadata; names belong in your own metadata or AnnData.</p>',9)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
